using System;using System.Linq;using System.Windows;using System.Windows.Controls;using System.Windows.Media;
class InstallerWizardLayoutTests {
 [STAThread]static int Main(){var app=new Application();int checks=0;foreach(double scale in new[]{1.0,1.25,1.5,2.0})foreach(int state in new[]{0,1,2}){var w=new InstallerWizard("v6.0.0");var root=(FrameworkElement)w.Content;var flags=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic;var primary=(Button)typeof(InstallerWizard).GetField("primary",flags).GetValue(w);var settings=(Button)typeof(InstallerWizard).GetField("settings",flags).GetValue(w);var secondary=(Button)typeof(InstallerWizard).GetField("secondary",flags).GetValue(w);settings.Visibility=state==1?Visibility.Visible:Visibility.Collapsed;primary.Content=state==2?"Open Sentinel":"Install Sentinel";secondary.Content=state==1?"Check again":state==2?"Set up Chrome":"Close";root.LayoutTransform=new ScaleTransform(scale,scale);foreach(var logical in new[]{new Size(560,470),new Size(780,560),new Size(1100,720)}){var size=new Size(logical.Width*scale,logical.Height*scale);root.Measure(size);root.Arrange(new Rect(size));root.UpdateLayout();foreach(var b in new[]{primary,settings,secondary}.Where(b=>b.Visibility==Visibility.Visible)){var bounds=b.TransformToAncestor(root).TransformBounds(new Rect(b.RenderSize));if(b.ActualHeight<44||bounds.Top<0||bounds.Bottom>root.ActualHeight+0.5||bounds.Right>root.ActualWidth+0.5||b.DesiredSize.Width-b.Margin.Left-b.Margin.Right>b.ActualWidth+0.5)throw new Exception("Clipped action: "+b.Content+" at "+size+" scale "+scale+" bounds="+bounds+" root="+root.ActualWidth+","+root.ActualHeight+" actual="+b.ActualWidth+","+b.ActualHeight+" desired="+b.DesiredSize);checks++;}}w.Close();}Console.WriteLine("PASS "+checks+" button layout checks, compact/standard/large sizes and simulated DPI scale cases");return 0;}
}
